<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { BarChart3, CalendarDays, CalendarPlus, CheckCircle2, Clock3, RefreshCw, TrendingUp, UserRound, Users, XCircle } from 'lucide-vue-next'
import { TENANT_NAVIGATION_EVENT, openAgendaOperator } from './tenantNavigation'

type Appointment={id:string;starts_at:string;status:string;customer_name:string;service_name?:string|null;professional_name:string}
type Report={synthetic:{appointments:number;unique_customers:number;completed:number;cancelled:number;no_show:number;estimated_revenue:number;completion_rate:number;no_show_rate:number};analytical:{curve:Array<{date:string;appointments:number}>;services:Array<{name:string;count:number}>;statuses:Array<{status:string;count:number}>}}
type Envelope<T>={data?:T;error?:{message?:string}}

const visible=ref(!window.location.hash||window.location.hash==='#dashboard')
const loading=ref(false)
const error=ref('')
const appointments=ref<Appointment[]>([])
const week=ref<Report|null>(null)
const month=ref<Report|null>(null)
const today=computed(()=>new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'}))
const todayKey=computed(()=>localKey(new Date()))
const todayItems=computed(()=>appointments.value.filter(item=>localKey(new Date(item.starts_at))===todayKey.value).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at)))
const nextItems=computed(()=>appointments.value.filter(item=>+new Date(item.starts_at)>=Date.now()&&!['CANCELLED','COMPLETED','NO_SHOW'].includes(item.status)).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at)).slice(0,6))
const maxCurve=computed(()=>Math.max(1,...(month.value?.analytical.curve.map(item=>item.appointments)||[1])))
const statusLabels:Record<string,string>={PENDING:'Pendente',AWAITING_CONFIRMATION:'Aguardando confirmação',CONFIRMED:'Confirmado',CHECKED_IN:'Check-in',IN_PROGRESS:'Em atendimento',COMPLETED:'Concluído',CANCELLED:'Cancelado',RESCHEDULED:'Reagendado',NO_SHOW:'Não compareceu'}

function token(){return localStorage.getItem('scheduler_pro_access_token')||''}
function localKey(value:Date){const offset=value.getTimezoneOffset()*60000;return new Date(value.getTime()-offset).toISOString().slice(0,10)}
function money(value=0){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value)}
function time(value:string){return new Date(value).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}
function dateTime(value:string){return new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function status(value:string){return statusLabels[value]||value}
async function api<T>(path:string):Promise<T>{const response=await fetch(`/api/v1${path}`,{cache:'no-store',headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const payload=await response.json().catch(()=>({})) as Envelope<T>;if(!response.ok)throw new Error(payload.error?.message||`Falha HTTP ${response.status}`);return payload.data as T}
async function load(){if(!visible.value||loading.value)return;loading.value=true;error.value='';try{const anchor=localKey(new Date());const [items,w,m]=await Promise.all([api<Appointment[]>('/appointments'),api<Report>(`/agenda/reports/summary?period=week&anchor=${anchor}`),api<Report>(`/agenda/reports/summary?period=month&anchor=${anchor}`)]);appointments.value=items;week.value=w;month.value=m}catch(exc){error.value=exc instanceof Error?exc.message:'Não foi possível atualizar a visão geral.'}finally{loading.value=false}}
function goAgenda(){window.history.replaceState(null,'','#agenda');window.dispatchEvent(new CustomEvent(TENANT_NAVIGATION_EVENT,{detail:{hash:'#agenda'}}))}
function sync(){visible.value=!window.location.hash||window.location.hash==='#dashboard';document.body.classList.toggle('sp-dashboard-insights-open',visible.value);if(visible.value)void load()}
function onNavigation(){sync()}
onMounted(()=>{window.addEventListener('hashchange',sync);window.addEventListener(TENANT_NAVIGATION_EVENT,onNavigation);sync()})
onUnmounted(()=>{window.removeEventListener('hashchange',sync);window.removeEventListener(TENANT_NAVIGATION_EVENT,onNavigation);document.body.classList.remove('sp-dashboard-insights-open')})
</script>

<template>
  <Teleport v-if="visible" to=".tenant-console .main-content">
    <section class="sp-dashboard-insights">
      <header><div><span>Visão geral</span><h1>Operação em tempo real</h1><p>{{today}} · acompanhe agenda, atendimento, receita estimada e próximos compromissos.</p></div><div><button :disabled="loading" @click="load"><RefreshCw :size="16" :class="{spin:loading}"/>Atualizar</button><button @click="goAgenda"><CalendarDays :size="16"/>Agenda</button><button class="primary" @click="openAgendaOperator({tab:'quick'})"><CalendarPlus :size="16"/>Novo</button></div></header>
      <p v-if="error" class="sp-dashboard-error">{{error}}</p>
      <div class="sp-dashboard-metrics"><article><CalendarDays/><span>Hoje</span><strong>{{todayItems.length}}</strong><small>atendimento(s)</small></article><article><Users/><span>Semana</span><strong>{{week?.synthetic.appointments||0}}</strong><small>{{week?.synthetic.unique_customers||0}} cliente(s)</small></article><article><TrendingUp/><span>Mês</span><strong>{{month?.synthetic.appointments||0}}</strong><small>agendamentos</small></article><article><CheckCircle2/><span>Conclusão</span><strong>{{month?.synthetic.completion_rate||0}}%</strong><small>{{month?.synthetic.completed||0}} concluído(s)</small></article><article><XCircle/><span>Não compareceu</span><strong>{{month?.synthetic.no_show_rate||0}}%</strong><small>{{month?.synthetic.no_show||0}} falta(s)</small></article><article><BarChart3/><span>Receita estimada</span><strong class="money">{{money(month?.synthetic.estimated_revenue||0)}}</strong><small>mês atual</small></article></div>
      <div class="sp-dashboard-grid">
        <article class="sp-dashboard-card"><header><div><span>Próximos</span><h2>Agenda em andamento</h2></div><button @click="goAgenda">Ver Agenda</button></header><div class="sp-next-list"><button v-for="item in nextItems" :key="item.id" @click="openAgendaOperator({tab:'manage'})"><div class="when"><strong>{{time(item.starts_at)}}</strong><small>{{new Date(item.starts_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}}</small></div><div><strong>{{item.customer_name}}</strong><small>{{item.service_name||'Sem serviço'}} · {{item.professional_name}}</small></div><em>{{status(item.status)}}</em></button><div v-if="!nextItems.length" class="empty"><CalendarDays :size="36"/><strong>Nenhum próximo atendimento.</strong><button @click="openAgendaOperator({tab:'quick'})">Criar agendamento</button></div></div></article>
        <article class="sp-dashboard-card"><header><div><span>Curva mensal</span><h2>Volume de atendimentos</h2></div></header><div class="sp-dashboard-curve"><div v-for="item in month?.analytical.curve||[]" :key="item.date"><span>{{new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}}</span><i><b :style="{width:`${Math.max(4,item.appointments*100/maxCurve)}%`}"></b></i><strong>{{item.appointments}}</strong></div><div v-if="!month?.analytical.curve.length" class="empty compact">Sem movimento no mês.</div></div></article>
        <article class="sp-dashboard-card"><header><div><span>Hoje</span><h2>Resumo do dia</h2></div></header><div class="sp-today-list"><div v-for="item in todayItems.slice(0,8)" :key="item.id"><Clock3 :size="15"/><time>{{time(item.starts_at)}}</time><strong>{{item.customer_name}}</strong><span>{{status(item.status)}}</span></div><div v-if="!todayItems.length" class="empty compact">Nenhum atendimento hoje.</div></div></article>
        <article class="sp-dashboard-card"><header><div><span>Serviços</span><h2>Mais agendados no mês</h2></div></header><div class="sp-ranking"><div v-for="item in month?.analytical.services.slice(0,8)||[]" :key="item.name"><span>{{item.name}}</span><strong>{{item.count}}</strong></div><div v-if="!month?.analytical.services.length" class="empty compact">Sem dados no mês.</div></div></article>
      </div>
    </section>
  </Teleport>
</template>

<style>
body.sp-dashboard-insights-open .tenant-console .main-content>.page-header,body.sp-dashboard-insights-open .tenant-console .main-content>.success-banner,body.sp-dashboard-insights-open .tenant-console .main-content>.error-banner,body.sp-dashboard-insights-open .tenant-console .main-content>.view-stack{display:none!important}.sp-dashboard-insights{padding:2px 0 84px;color:#10213b}.sp-dashboard-insights>header{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;margin-bottom:18px}.sp-dashboard-insights>header>div:first-child{max-width:760px}.sp-dashboard-insights header span,.sp-dashboard-card header span{color:#2563eb;font-size:10px;font-weight:900;letter-spacing:.11em;text-transform:uppercase}.sp-dashboard-insights h1{margin:5px 0 6px;font-size:34px;letter-spacing:-.04em}.sp-dashboard-insights>header p{margin:0;color:#52647c;font-size:13px}.sp-dashboard-insights>header>div:last-child{display:flex;gap:7px}.sp-dashboard-insights>header button{min-height:41px;border:1px solid #d9e3ef;border-radius:10px;background:#fff;color:#233a55;padding:0 12px;display:flex;align-items:center;gap:6px;font:inherit;font-size:10px;font-weight:850}.sp-dashboard-insights>header button.primary{background:#2563eb;border-color:#2563eb;color:#fff}.sp-dashboard-error{padding:10px 13px;border-radius:11px;background:#fff1f2;color:#be123c}.sp-dashboard-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:14px}.sp-dashboard-metrics article{position:relative;min-height:126px;padding:17px;border:1px solid #dce5ef;border-radius:17px;background:#fff;display:flex;flex-direction:column;justify-content:flex-end;overflow:hidden}.sp-dashboard-metrics article>svg{position:absolute;right:14px;top:14px;width:23px;color:#94a3b8}.sp-dashboard-metrics article>span{color:#5f7188;font-size:9px;font-weight:900;text-transform:uppercase}.sp-dashboard-metrics article>strong{margin:5px 0 1px;font-size:25px;color:#102a4d}.sp-dashboard-metrics article>strong.money{font-size:18px}.sp-dashboard-metrics article>small{color:#64778f}.sp-dashboard-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:14px}.sp-dashboard-card{border:1px solid #dce5ef;border-radius:18px;background:#fff;padding:18px}.sp-dashboard-card>header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding-bottom:12px;border-bottom:1px solid #edf1f6}.sp-dashboard-card h2{margin:4px 0 0;font-size:18px}.sp-dashboard-card header button{border:1px solid #dce5ef;border-radius:9px;background:#fff;color:#1d4ed8;padding:7px 9px;font-size:10px;font-weight:850}.sp-next-list,.sp-today-list,.sp-ranking,.sp-dashboard-curve{display:grid;gap:7px;margin-top:12px}.sp-next-list>button{display:grid;grid-template-columns:58px minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px;border:1px solid #e5eaf1;border-radius:11px;background:#fff;color:#223650;text-align:left}.sp-next-list .when strong,.sp-next-list .when small,.sp-next-list>button>div:nth-child(2) strong,.sp-next-list>button>div:nth-child(2) small{display:block}.sp-next-list .when strong{color:#1d4ed8}.sp-next-list small{margin-top:2px;color:#64778f}.sp-next-list em{font-style:normal;color:#53657d;font-size:9px;font-weight:800}.sp-dashboard-curve>div{display:grid;grid-template-columns:48px minmax(0,1fr) 28px;gap:8px;align-items:center;color:#65768d;font-size:9px}.sp-dashboard-curve i{height:8px;border-radius:999px;background:#edf2f7;overflow:hidden}.sp-dashboard-curve b{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#2563eb,#22c1dc)}.sp-dashboard-curve strong{text-align:right;color:#17345d}.sp-today-list>div{display:grid;grid-template-columns:auto 48px minmax(0,1fr) auto;gap:7px;align-items:center;padding:9px;border-radius:9px;background:#f8fafc;font-size:10px}.sp-today-list svg{color:#2563eb}.sp-today-list span{color:#64748b}.sp-ranking>div{display:flex;justify-content:space-between;padding:9px 10px;border-radius:9px;background:#f8fafc;color:#40536c;font-size:11px}.empty{min-height:150px;display:grid;place-items:center;align-content:center;gap:6px;text-align:center;color:#718198}.empty.compact{min-height:80px}.empty button{border:0;border-radius:9px;background:#2563eb;color:#fff;padding:8px 11px}.spin{animation:dashboard-spin .9s linear infinite}@keyframes dashboard-spin{to{transform:rotate(360deg)}}
@media(max-width:1150px){.sp-dashboard-metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.sp-dashboard-insights>header{display:grid}.sp-dashboard-insights>header>div:last-child{display:grid;grid-template-columns:1fr 1fr 1fr}.sp-dashboard-insights>header button{justify-content:center}.sp-dashboard-grid{grid-template-columns:1fr}.sp-dashboard-metrics{grid-template-columns:1fr 1fr}}@media(max-width:520px){.sp-dashboard-insights{padding-bottom:76px}.sp-dashboard-insights h1{font-size:29px}.sp-dashboard-insights>header>div:last-child{grid-template-columns:1fr}.sp-dashboard-metrics article{min-height:105px}.sp-next-list>button{grid-template-columns:50px minmax(0,1fr)}.sp-next-list em{grid-column:2}.sp-today-list>div{grid-template-columns:auto 44px minmax(0,1fr)}.sp-today-list span{grid-column:3}}
</style>
